sys_script_client.script:
/**
 * 销假小时数变更时的校验脚本
 * 功能：校验销假小时数，不允许超过请假单的最大请假小时数
 */
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    // 页面加载中 或 值为空时，不执行校验
    if (isLoading || newValue === '') {
        return;
    }

    // 清空表单上的所有错误提示信息
    g_form.clearMessages();

    // 获取当前输入的【销假小时数】，转为数字类型，空值默认为0
    var cancelHour = parseFloat(newValue) || 0;

    /**
     * 通过Reference字段【leave_num】获取关联的请假单信息
     * g_form.getReference( reference字段名, 回调函数 )
     * grLeave：回调返回的请假单对象（包含所有关联表字段）
     */
    g_form.getReference('leave_num', function(grLeave) {
        // 从关联的请假单中，获取【请假总小时数】，空值默认为0
        var leaveHour = grLeave.leave_hour || 0;

        // 销假小时数 > 请假小时数 → 报错
        if (cancelHour > leaveHour) {
            g_form.addErrorMessage('• 销假小时数不能超过请假小时数(' + leaveHour + 'h)');
        } 
        // 数据正常 → 清空错误提示
        else {
            g_form.clearMessages();
        }
    });
}
